-- DietPal push reminders — Supabase setup (already applied to project "dietpal", ref jlbdtmzccrebjmlrjvgh).
-- Kept here for reference / re-creating the project.

create extension if not exists pg_cron;
create extension if not exists pg_net schema extensions;

-- Server-only settings: VAPID keys (generated by the Edge Function on first run) and the cron secret.
create table public.push_config (key text primary key, value text not null);

-- One row per phone that turned on reminders. No name, weight or food list.
create table public.push_subs (
  endpoint   text primary key,
  p256dh     text not null,
  auth       text not null,
  tz         text not null default 'Asia/Kuala_Lumpur',
  prefs      jsonb not null default '{}'::jsonb,   -- meal times, which reminders are on, weigh day
  status     jsonb not null default '{}'::jsonb,   -- today: meals logged (yes/no), water ml, kcal total, last weigh-in date
  sent       jsonb not null default '{}'::jsonb,   -- reminders already sent today + time of the last one
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- RLS on with no policies: only the service role (the Edge Function) can read or write.
alter table public.push_config enable row level security;
alter table public.push_subs enable row level security;
revoke all on public.push_config from anon, authenticated;
revoke all on public.push_subs from anon, authenticated;

insert into public.push_config (key, value) values ('cron_secret', encode(extensions.gen_random_bytes(32), 'hex'));

-- Every 15 minutes: the Edge Function checks who is due a reminder.
select cron.schedule('dietpal-push', '*/15 * * * *', $$
  select net.http_post(
    url := 'https://jlbdtmzccrebjmlrjvgh.supabase.co/functions/v1/push',
    body := '{"action":"run"}'::jsonb,
    headers := jsonb_build_object('content-type', 'application/json',
      'x-cron-secret', (select value from public.push_config where key = 'cron_secret')),
    timeout_milliseconds := 30000);
$$);
